using AppCondominio.Modules.SecurityOperations.Application;using AppCondominio.Modules.SecurityOperations.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Testcontainers.MsSql;
namespace AppCondominio.IntegrationTests;
public sealed class GuardPortalPersistenceTests:IAsyncLifetime
{
 private readonly MsSqlContainer _sql=new MsSqlBuilder("mcr.microsoft.com/mssql/server:2022-latest").Build();public Task InitializeAsync()=>_sql.StartAsync();public Task DisposeAsync()=>_sql.DisposeAsync().AsTask();
 [Fact] public async Task Guard_portal_is_scoped_to_assigned_community(){IConfiguration c=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"ConnectionStrings:SecurityOperations",_sql.GetConnectionString()}}).Build();var services=new ServiceCollection();services.AddSecurityOperationsModule(c);await using var p=services.BuildServiceProvider();await using(var scope=p.CreateAsyncScope()){await scope.ServiceProvider.GetRequiredService<SecurityOperationsDbContext>().Database.MigrateAsync();}
 var communityA=Guid.NewGuid();var communityB=Guid.NewGuid();Guid visitA,visitB;await using(var scope=p.CreateAsyncScope()){var svc=scope.ServiceProvider.GetRequiredService<SecurityOperationsService>();await svc.GrantGuardPortalAccessAsync(communityA,"portal-guard-a","Guard A",DateTimeOffset.UtcNow.AddDays(1),default);visitA=await svc.AuthorizeVisitAsync(communityA,Guid.NewGuid(),"Visitor A","DOC-A","Tower A",DateTimeOffset.UtcNow.AddMinutes(-10),DateTimeOffset.UtcNow.AddHours(2),default);visitB=await svc.AuthorizeVisitAsync(communityB,Guid.NewGuid(),"Visitor B","DOC-B","Tower B",DateTimeOffset.UtcNow.AddMinutes(-10),DateTimeOffset.UtcNow.AddHours(2),default);var ctx=await svc.GetGuardPortalContextAsync("portal-guard-a",default);Assert.Equal(communityA,ctx.CommunityId);var visits=await svc.GetGuardVisitsAsync("portal-guard-a",DateTimeOffset.UtcNow.AddHours(-1),DateTimeOffset.UtcNow.AddHours(3),default);Assert.Single(visits);Assert.Equal(visitA,visits[0].Id);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>svc.CheckInForGuardAsync("portal-guard-a",visitB,DateTimeOffset.UtcNow,"Gate B",default));await svc.CheckInForGuardAsync("portal-guard-a",visitA,DateTimeOffset.UtcNow,"Gate A",default);await svc.CheckOutForGuardAsync("portal-guard-a",visitA,DateTimeOffset.UtcNow.AddMinutes(1),default);var incidentId=await svc.ReportGuardIncidentAsync("portal-guard-a","Access","Test incident","Gate A",default);Assert.NotEqual(Guid.Empty,incidentId);await Assert.ThrowsAsync<InvalidOperationException>(()=>svc.GrantGuardPortalAccessAsync(communityB,"portal-guard-a","Other Guard",DateTimeOffset.UtcNow.AddDays(1),default));}
 await using(var scope=p.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SecurityOperationsDbContext>();var incident=await db.Incidents.SingleAsync();Assert.Equal(communityA,incident.CommunityId);Assert.Equal("Guard A",incident.ReportedBy);Assert.Single(await db.GuardAccessGrants.ToArrayAsync());var persistedA=await db.Visits.SingleAsync(x=>x.Id==visitA);var persistedB=await db.Visits.SingleAsync(x=>x.Id==visitB);Assert.Equal(AppCondominio.Modules.SecurityOperations.Domain.VisitStatus.CheckedOut,persistedA.Status);Assert.Equal(AppCondominio.Modules.SecurityOperations.Domain.VisitStatus.Authorized,persistedB.Status);}}
}